import axios from 'axios';
import { motion } from "framer-motion";
import React, { useEffect, useState } from "react";
import { useInView } from "react-intersection-observer";
import awsImage from "../assets/aws.jpg";
import fsdImage from "../assets/fsd.jpg";
import mlintImage from "../assets/mlint.jpg";
import resImage from "../assets/res.jpg";
import { GlareCard } from "../components/GlareCard";
import "../styles/Services.css";
import { staggerContainer, zoomIn } from "../utils/animations";

const Services = () => {
  const [services, setServices] = useState([]);
  const [ref, inView] = useInView({
    triggerOnce: true,
    threshold: 0.1
  });

  useEffect(() => {
    axios.get("http://localhost:8000/services")
      .then(res => setServices(res.data))
      .catch(err => console.error(err));
  }, []);

  const serviceCards = [
    {
      image: resImage,
      title: "RESPONSIVE DESIGN",
      description: "Improving user involvement with flexible designs that work smoothly across all types of devices"
    },
    {
      image: fsdImage,
      title: "FULL-STACK DEVELOPMENT",
      description: "I use React-Flask/fastapi stack to build and deploy full-stack web applications efficiently."
    },
    {
      image: awsImage,
      title: "WORKFLOW AUTOMATION",
      description: "Providing AI-driven marketing tools, automation agents, and integrations that streamline digital workflows."
    },
    {
      image: mlintImage,
      title: "AI & ML-INTEGRATION",
      description: "Integrating trained AI/ML models into apps for smart recommendations, predictions, and classifications."
    }
  ];

  return (
    <section id="services" className="services-section">
      <motion.h2 
        className="section-title"
        initial={{ opacity: 0, y: 20 }}
        animate={inView ? { opacity: 1, y: 0 } : { opacity: 0, y: 20 }}
        transition={{ duration: 0.6 }}
      >
        My Services
      </motion.h2>
      <motion.p 
        className="services-subtitle"
        initial={{ opacity: 0 }}
        animate={inView ? { opacity: 1 } : { opacity: 0 }}
        transition={{ duration: 0.6, delay: 0.2 }}
      >
        What services I provide -
      </motion.p>
      <motion.div 
        ref={ref}
        className="services-container"
        variants={staggerContainer}
        initial="initial"
        animate={inView ? "animate" : "initial"}
      >
        {serviceCards.map((service, index) => (
          <motion.div 
            key={index}
            className="service-card"
            variants={zoomIn}
          >
            <GlareCard variant="primary" className="w-64">
              <div className="flex flex-col items-center p-6">
                <motion.img 
                  src={service.image} 
                  alt={service.title} 
                  className="w-16 h-16 mb-4"
                />
                <h3 className="text-lg font-bold mb-2">{service.title}</h3>
                <p className="text-sm text-gray-300 text-center">
                  {service.description}
                </p>
              </div>
            </GlareCard>
          </motion.div>
        ))}
      </motion.div>
    </section>
  );
};

export default Services;
